"""Add datasets: named, versionless collections of evaluation items.

Revision ID: 0503
Revises: 0502
Create Date: 2026-10-10

A dataset is a set of items an experiment replays through a prompt and model: an `input`, an
optional `expected_output` and free-form `metadata`. Items may remember the trace and span they
were copied from.

Choices worth knowing about:

* Ids are UUIDv7 generated by the application, so no column has a default.
* `datasets` carries `project_id` and cascades from `projects`; `UNIQUE (project_id, name)`
  keeps names apart within a project, because the name is the handle the CLI and the CI action
  use.
* `dataset_items` has no `project_id`: it belongs to its dataset and cascades from it. Its
  row-level security policy asks whether the dataset is visible, so an item is exactly as visible
  as its dataset. The policy uses the same InitPlan form as the project policies.
* `source_trace_id` and `source_span_id` are plain text, not foreign keys: traces are deleted by
  retention and an item must outlive the trace it came from.
* The item count limit (10 000 per dataset) and the payload sizes are checked by the API, not
  by the database.
* Indexes: `(dataset_id, id)` serves the keyset listing of a dataset's items; `created_by` is
  indexed so deleting a user does not scan the table.

The migration creates new tables only, in one transaction. Downgrade drops them.
"""

from collections.abc import Sequence

from alembic import op

revision: str = "0503"
down_revision: str | None = "0502"
branch_labels: str | Sequence[str] | None = None
depends_on: str | Sequence[str] | None = None

PROJECT_EXPRESSION = (
    "project_id = (SELECT NULLIF(current_setting('app.project_id', true), '')::uuid)"
)
BYPASS_EXPRESSION = "(SELECT current_setting('app.bypass_rls', true)) = 'on'"
ITEM_EXPRESSION = "EXISTS (SELECT 1 FROM datasets d WHERE d.id = dataset_items.dataset_id)"


def upgrade() -> None:
    _create_tables()
    _enable_rls()


def _create_tables() -> None:
    op.execute(
        """
        CREATE TABLE datasets (
            id           uuid PRIMARY KEY,
            project_id   uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
            name         text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
            description  text CHECK (char_length(description) <= 1000),
            created_by   uuid REFERENCES users (id) ON DELETE SET NULL,
            created_at   timestamptz NOT NULL DEFAULT now(),
            updated_at   timestamptz NOT NULL DEFAULT now(),
            CONSTRAINT datasets_project_name_key UNIQUE (project_id, name)
        )
        """
    )
    op.execute("CREATE INDEX datasets_created_by_idx ON datasets (created_by)")
    op.execute(
        """
        CREATE TABLE dataset_items (
            id               uuid PRIMARY KEY,
            dataset_id       uuid NOT NULL REFERENCES datasets (id) ON DELETE CASCADE,
            input            jsonb NOT NULL,
            expected_output  jsonb,
            metadata         jsonb NOT NULL DEFAULT '{}',
            source_trace_id  text,
            source_span_id   text,
            created_at       timestamptz NOT NULL DEFAULT now()
        )
        """
    )
    op.execute("CREATE INDEX dataset_items_dataset_idx ON dataset_items (dataset_id, id)")


def _enable_rls() -> None:
    op.execute("ALTER TABLE datasets ENABLE ROW LEVEL SECURITY")
    op.execute("ALTER TABLE datasets FORCE ROW LEVEL SECURITY")
    op.execute(
        "CREATE POLICY datasets_project_isolation ON datasets "
        f"USING ({PROJECT_EXPRESSION}) WITH CHECK ({PROJECT_EXPRESSION})"
    )
    op.execute(
        "CREATE POLICY datasets_worker_bypass ON datasets "
        f"USING ({BYPASS_EXPRESSION}) WITH CHECK ({BYPASS_EXPRESSION})"
    )
    op.execute("ALTER TABLE dataset_items ENABLE ROW LEVEL SECURITY")
    op.execute("ALTER TABLE dataset_items FORCE ROW LEVEL SECURITY")
    op.execute(
        "CREATE POLICY dataset_items_project_isolation ON dataset_items "
        f"USING ({ITEM_EXPRESSION}) WITH CHECK ({ITEM_EXPRESSION})"
    )
    op.execute(
        "CREATE POLICY dataset_items_worker_bypass ON dataset_items "
        f"USING ({BYPASS_EXPRESSION}) WITH CHECK ({BYPASS_EXPRESSION})"
    )


def downgrade() -> None:
    op.execute("DROP TABLE IF EXISTS dataset_items")
    op.execute("DROP TABLE IF EXISTS datasets")
